/* @autogenerated */
package net.civeira.phylax.feature.observe.probe;

import java.util.List;
import java.util.Set;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.feature.observe.metric.MetricPoint;

class ProbeUnitTest {

  @Test
  @DisplayName("Only http(s) URLs of the allowed hosts, never link-local addresses")
  void forbidden() {
    Set<String> allowed = Set.of("localhost", "169.254.169.254");
    Assertions.assertNull(ProbeCheck.forbidden("http://localhost:8080/q/health", allowed));
    Assertions.assertNotNull(ProbeCheck.forbidden("file:///etc/passwd", allowed));
    Assertions.assertNotNull(ProbeCheck.forbidden("https://intranet.local/admin", allowed));
    Assertions
        .assertNotNull(ProbeCheck.forbidden("http://169.254.169.254/latest/meta-data", allowed));
    Assertions.assertNotNull(ProbeCheck.forbidden("not a url", allowed));
  }

  @Test
  @DisplayName("Availability of the checks since a moment, and the allowed hosts list")
  void availability() {
    List<MetricPoint> points =
        List.of(new MetricPoint(1_000, 60_000, "api", "probe home", "PROBE", 10, 1, 0, null),
            new MetricPoint(5_000, 60_000, "api", "probe home", "PROBE", 10, 0, 0, null));
    Assertions.assertEquals(95.0, ProbeRunner.availability(points, 0));
    Assertions.assertEquals(100.0, ProbeRunner.availability(points, 2_000));
    Assertions.assertNull(ProbeRunner.availability(List.of(), 0));
    Assertions.assertEquals(Set.of("a.test", "b.test"), ProbeRunner.hosts(" A.test, b.test ,"));
  }
}
